/**
 * Shared formatting utilities for tool call display.
 *
 * Used by both:
 * - ui/components/ToolCall.tsx (Ink REPL)
 * - cli/output/renderer.ts (headless text output)
 */

import { sep } from "node:path";

/** Maximum preview lines for tool output. */
export const MAX_PREVIEW_LINES = 4;
export const MAX_LINE_WIDTH = 88;

/**
 * Argument keys that carry filesystem paths. Values for these keys are
 * relativized against process.cwd() before display so users see
 * "src/ui/App.tsx" instead of "/Users/.../codeshell/src/ui/App.tsx".
 */
const PATH_ARG_KEYS = new Set(["file_path", "path", "directory", "cwd"]);

/**
 * Strip the cwd prefix from a path string for display. Paths outside
 * cwd, relative paths, and non-string values are returned unchanged.
 */
function relativizePath(value: string): string {
  if (!value || !value.startsWith("/")) return value;
  const cwd = process.cwd();
  const prefix = cwd.endsWith(sep) ? cwd : cwd + sep;
  if (value === cwd) return ".";
  if (value.startsWith(prefix)) return value.slice(prefix.length);
  return value;
}

/** Tool name → display color for the dot indicator. */
export const TOOL_DOT_COLORS: Record<string, string> = {
  Read: "ansi:blue",
  Write: "ansi:green",
  Edit: "ansi:yellow",
  Bash: "ansi:magenta",
  Glob: "ansi:blue",
  Grep: "ansi:blue",
  Agent: "ansi:cyan",
  WebSearch: "ansi:blue",
  WebFetch: "ansi:blue",
  LSP: "ansi:cyan",
  TodoWrite: "ansi:cyan",
};

/** Mapping of tool names to their most informative argument keys. */
const TOOL_ARG_KEYS: Record<string, string[]> = {
  Read: ["file_path"],
  Write: ["file_path"],
  Edit: ["file_path"],
  Glob: ["pattern"],
  Grep: ["pattern", "path"],
  Bash: ["command"],
  WebSearch: ["query"],
  WebFetch: ["url"],
  Agent: ["description"],
  TodoWrite: ["todos"],
  Sleep: ["seconds"],
  EnterWorktree: ["target", "slug"],
  CronCreate: ["name", "schedule"],
  LSP: ["action", "file_path"],
  NotebookEdit: ["action", "file_path"],
  Config: ["action", "key"],
};

/**
 * Strip a leading `cd <dir> && ` (or `; `) so the visible command is the
 * thing the user actually cares about. The cwd prefix is mechanical noise
 * that otherwise eats the entire truncation budget on long absolute paths.
 */
function stripCdPrefix(cmd: string): string {
  // Matches: cd <path> && rest   |   cd "<path with spaces>" && rest   |   cd '...'; rest
  const m = cmd.match(/^\s*cd\s+(?:"[^"]*"|'[^']*'|\S+)\s*(?:&&|;)\s*(.+)$/s);
  return m ? m[1]!.trim() : cmd;
}

/**
 * Format tool arguments into a compact one-line summary.
 */
export function formatToolArgs(toolName: string, args: Record<string, unknown>): string {
  const keys = TOOL_ARG_KEYS[toolName] ?? Object.keys(args).slice(0, 2);
  const parts: string[] = [];
  for (const k of keys) {
    const v = args[k];
    if (v !== undefined && !k.startsWith("__")) {
      let s = String(v);
      if (toolName === "Bash" && k === "command") s = stripCdPrefix(s);
      else if (PATH_ARG_KEYS.has(k)) s = relativizePath(s);
      // Bash commands deserve more room than other args — the truncation
      // budget here used to swallow `git diff …` after a long cd prefix.
      const max = toolName === "Bash" && k === "command" ? MAX_LINE_WIDTH : 60;
      parts.push(truncate(s, max));
    }
  }
  // Read often pages large files via offset/limit — show a range suffix so
  // back-to-back reads of the same file are visually distinguishable.
  if (toolName === "Read") {
    const offset = typeof args.offset === "number" ? args.offset : undefined;
    const limit = typeof args.limit === "number" ? args.limit : undefined;
    if (offset !== undefined || limit !== undefined) {
      const start = offset ?? 1;
      const end = limit !== undefined ? start + limit - 1 : undefined;
      parts.push(end !== undefined ? `:${start}-${end}` : `:${start}-`);
    }
  }
  return parts.length > 0 ? parts.join(" ") : truncate(JSON.stringify(args), 80);
}

/** Truncate a string to max length with ellipsis. */
export function truncate(s: string, max: number): string {
  return s.length > max ? s.slice(0, max - 1) + "…" : s;
}

interface ToolCallStartProps {
  toolName: string;
  args: Record<string, unknown>;
  nested?: boolean;
}

export function ToolCallStart({ toolName, args, nested }: ToolCallStartProps) {
  const argsStr = formatToolArgs(toolName, args);
  const dotColor = TOOL_DOT_COLORS[toolName] ?? "ansi:cyan";
  const ml = nested ? 3 : 0;

  // Top-level tool blocks get a blank line above them so back-to-back tool
  // calls don't visually fuse into one wall (matches Claude Code's spacing).
  // Nested (under Agent) stays tight because the agent block already groups.
  return (
    <Box marginLeft={ml} marginTop={nested ? 0 : 1}>
      <Text color={dotColor}>{"  ●"}</Text>
      <Text bold> {toolName}</Text>
      <Text dim>
        {"  "}
        {argsStr}
      </Text>
    </Box>
  );
}

export class TextRenderer implements OutputRenderer {
  private activeAgents = new Set<string>();

  onEvent(event: StreamEvent): void {
    const agentId = (event as any).agentId as string | undefined;
    const indent = agentId ? "    " : "";
    const prefix = agentId ? chalk.dim("│ ") : "";

    switch (event.type) {

case "agent_end": {
  const ev = event as any;
  this.activeAgents.delete(ev.agentId);
  const endType = ev.agentType ? `[${ev.agentType}] ` : "";
  if (ev.error) {
    process.stderr.write(`${indent}${chalk.red("✗")} ${chalk.dim(`Agent ${endType}${ev.description}: ${ev.error}`)}\n`);
  } else {
    process.stderr.write(`${indent}${chalk.green("✓")} ${chalk.dim(`Agent ${endType}${ev.description}`)}\n`);
  }
  break;
}

case "tool_use_start": {
  const tc = event.toolCall;
  const argsStr = formatToolArgs(tc.toolName, tc.args);
  process.stderr.write(`${indent}${prefix}${chalk.cyan("●")} ${chalk.bold(tc.toolName)} ${chalk.dim(argsStr)}\n`);
  break;
}

case "tool_result": {

    "For images and binary files, returns path/metadata instead of raw bytes. " +
    "For large text files, consider using Grep first to find the relevant lines.\n\n" +
    "Do NOT re-read a file you just edited to verify — Edit/Write would have errored " +
    "if the change failed.\n" +
    "Do NOT re-read a file (or the same range of a file) you've already read earlier in " +
    "this conversation. The content is already in your context. If you need a different " +
    "part of the file, read a different offset; otherwise decide with what you have.",
  inputSchema: {
    type: "object",
    properties: {
      file_path: { type: "string", description: "Absolute path to the file to read" },
      offset: { type: "number", description: "Line number to start reading from (1-based)" },
      limit: { type: "number", description: "Number of lines to read (default: 2000)" },
    },
    required: ["file_path"],
  },
};

